// FiberServerOptions provides options for the Fiber server.
type FiberServerOptions struct {
	BaseURL            string
	Middlewares        []MiddlewareFunc
	HandlerMiddlewares []HandlerMiddlewareFunc
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router fiber.Router, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, FiberServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router fiber.Router, si ServerInterface, options FiberServerOptions) {
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.HandlerMiddlewares,
	}

	for _, m := range options.Middlewares {
		router.Use(fiber.Handler(m))
	}

	router.Get(options.BaseURL+"/healthz", wrapper.GetHealth)

	router.Get(options.BaseURL+"/v1/roles", wrapper.ListRoles)

	router.Post(options.BaseURL+"/v1/roles", wrapper.CreateRole)

	router.Get(options.BaseURL+"/v1/roles/:slug", wrapper.GetRoleBySlug)

	router.Delete(options.BaseURL+"/v1/roles/:roleId", wrapper.DeleteRole)

	router.Patch(options.BaseURL+"/v1/roles/:roleId", wrapper.UpdateRole)

	router.Post(options.BaseURL+"/v1/roles/:roleId/topics", wrapper.CreateTopic)

	router.Delete(options.BaseURL+"/v1/topics/:topicId", wrapper.DeleteTopic)

	router.Patch(options.BaseURL+"/v1/topics/:topicId", wrapper.UpdateTopic)

	router.Put(options.BaseURL+"/v1/topics/:topicId/status", wrapper.SetTopicStatus)

	router.Post(options.BaseURL+"/v1/topics/:topicId/resources", wrapper.CreateResource)

	router.Delete(options.BaseURL+"/v1/resources/:resourceId", wrapper.DeleteResource)

	router.Patch(options.BaseURL+"/v1/resources/:resourceId", wrapper.UpdateResource)

	router.Post(options.BaseURL+"/v1/topics/:topicId/images", wrapper.UploadTopicImage)

	router.Delete(options.BaseURL+"/v1/images/:imageId", wrapper.DeleteTopicImage)

}

